   662      /* Not converted, no mem */
   663      if(!ba64)
   664          return UA_STATUSCODE_BADENCODINGERROR;
   665
   666      /* Check if negative... (TODO: Why is base64 3rd argument type int?) */
   667      if(flen < 0) {
